// Command Resend-cli is a CLI + REPL for the Resend SDK,
// built on the boru engine. Positional arguments are joined into a
// single boru expression and evaluated; with no arguments, falls into
// a REPL. Generated by sdkgen go-cli target.
package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"strings"

	eng "github.com/boru-lang/boru/eng/go"
	"github.com/boru-lang/boru/eng/go/parser"
	sdk "github.com/voxgig-sdk/resend-sdk/go"
)

// prompt is the REPL prompt prefix (matches the SDK slug).
const prompt = "resend"

// entitiesHelp is the space-separated entity list shown by /help.
const entitiesHelp = "add_contact_to_segment_response_success add_inbox_thread_labels_response_success api_key audience automation automation_run automation_run_list_item batch_add_suppressions_response_success batch_remove_suppressions_response_success broadcast contact contact_import_response_success contact_property contact_topics_response_success create_api_key create_batch_email create_broadcast_response_success create_inbox_draft_response_success create_inbox_label_response_success domain domain_claim email emails_metric event inbox inbox_agent_response_success inbox_draft_list_item inbox_draft_response_success inbox_label inbox_thread inbox_thread_email inbox_thread_email_response_success inbox_thread_response_success list_attachment list_broadcast_clicked_links_response_success list_broadcast_recipients_response_success list_contact_segments_response_success list_contacts_response_success list_webhook_event list_webhook_event_attempt log received_email remove_audience_response_success remove_broadcast_response_success remove_contact_from_segment_response_success remove_contact_property_response_success remove_contact_response_success remove_event remove_inbox_draft_response_success remove_inbox_label_response_success remove_inbox_response_success remove_inbox_thread_label_response_success remove_inbox_thread_response_success remove_segment_response_success remove_suppression_response_success remove_template_response_success remove_topic_response_success retrieved_attachment revoke_o_auth_grant rotate segment set_inbox_thread_labels_response_success suppression template topic update_api_key update_broadcast_response_success update_contact_property_response_success update_contact_response_success update_contact_topics_response_success update_domain_response_success update_email_option update_event update_inbox_draft_response_success update_inbox_label_response_success update_inbox_response_success update_inbox_thread_response_success update_segment_response_success update_template_response_success update_topic_response_success update_webhook usage webhook webhook_event"

func main() {
	os.Exit(run(os.Args[1:], os.Stdin, os.Stdout, os.Stderr))
}

// usage prints the CLI help (for --help / -h). No client or network setup.
func usage(out io.Writer) {
	fmt.Fprintf(out, "%s-cli — boru-driven CLI + REPL for the %s SDK\n\n", prompt, prompt)
	fmt.Fprintln(out, "Usage:")
	fmt.Fprintf(out, "  %s-cli [--help] [<boru expression>]\n\n", prompt)
	fmt.Fprintln(out, "With arguments, they are joined into a single boru expression and")
	fmt.Fprintln(out, "evaluated against the API. With no arguments, starts an interactive REPL.")
	fmt.Fprintln(out)
	fmt.Fprintln(out, "Words:    list / load / update <query?> <entity>")
	fmt.Fprintln(out, "Entities:", entitiesHelp)
	fmt.Fprintln(out, "Env:      RESEND_APIKEY (api key), RESEND_BASE (base url override)")
	fmt.Fprintln(out, "REPL:     /help  /quit")
}

func run(args []string, in io.Reader, out, errOut io.Writer) int {
	// --help / -h: print usage and exit before any config or network setup.
	for _, a := range args {
		if a == "--help" || a == "-h" {
			usage(out)
			return 0
		}
	}

	// Configure from the environment: RESEND_APIKEY carries the API key and
	// RESEND_BASE optionally overrides the API base URL (e.g. production).
	// Both injectable by a secrets vault. Unset -> nil config defaults.
	var opts map[string]any
	if apikey := os.Getenv("RESEND_APIKEY"); apikey != "" {
		opts = map[string]any{"apikey": apikey}
	}
	if base := os.Getenv("RESEND_BASE"); base != "" {
		if opts == nil {
			opts = map[string]any{}
		}
		opts["base"] = base
	}
	client := sdk.NewResendSDK(opts)

	r, err := eng.NewRegistry()
	if err != nil {
		fmt.Fprintf(errOut, "registry: %v\n", err)
		return 1
	}
	registerSDKWords(r, client)
	if err := r.Err(); err != nil {
		fmt.Fprintf(errOut, "word registration: %v\n", err)
		return 1
	}
	r.SetParseFunc(parser.Parse)
	r.InitRootContext()
	r.MarkReady()

	if len(args) > 0 {
		return evalOnce(r, strings.Join(args, " "), out, errOut)
	}
	repl(r, in, out)
	return 0
}

func evalOnce(r *eng.Registry, src string, out, errOut io.Writer) int {
	values, err := parser.Parse(src)
	if err != nil {
		fmt.Fprintf(errOut, "parse: %v\n", err)
		return 1
	}
	result, err := eng.NewTop(r).Run(values)
	if err != nil {
		fmt.Fprintf(errOut, "error: %v\n", err)
		return 1
	}
	for _, v := range result {
		fmt.Fprintln(out, v.String())
	}
	return 0
}

func repl(r *eng.Registry, in io.Reader, out io.Writer) {
	scanner := bufio.NewScanner(in)
	scanner.Buffer(make([]byte, 0, 64*1024), 1024*1024)
	for {
		fmt.Fprintf(out, "%s> ", prompt)
		if !scanner.Scan() {
			fmt.Fprintln(out)
			return
		}
		line := strings.TrimSpace(scanner.Text())
		if line == "" {
			continue
		}
		switch line {
		case "/quit", "/q", "/exit":
			return
		case "/help", "/h", "/?":
			fmt.Fprintln(out, "words:    list / load / update <query?> <entity>")
			fmt.Fprintln(out, "entities:", entitiesHelp)
			fmt.Fprintln(out, "meta:     /help  /quit")
			continue
		}
		values, err := parser.Parse(line)
		if err != nil {
			fmt.Fprintf(out, "  parse error: %v\n", err)
			continue
		}
		result, err := eng.NewTop(r).Run(values)
		if err != nil {
			fmt.Fprintf(out, "  error: %v\n", err)
			continue
		}
		for _, v := range result {
			fmt.Fprintln(out, v.String())
		}
	}
}
